export interface LongTextData {
  id: string;
  title: string;
  content: string;
  category: string; // 동화, 시, 수필, 칼럼, 소설
  difficulty: string; // 초급, 중급, 고급
  wordCount: number;
  author: string;
  source: string; // 출처 표기 필드
  isPremium?: boolean; // 선택적 프로퍼티로 변경 (기본값 false를 원할 경우 사용할 때 처리)
  seriesId?: string; // 연재물이면 소속 시리즈 ID
  episode?: number;  // 연재물이면 화 번호 (1부터)
}

/** 연재(장편) 시리즈 메타 — 오리지널 연재소설 등 */
export interface PilsaSeries {
  id: string;
  title: string;
  author: string;
  logline: string;
  totalEpisodes: number;
  description: string;
  /** 토큰 표지: 팔레트 × 패턴 (BookCoverArt 절차 생성) */
  cover?: { palette: string; pattern: string };
  /** 작가 프로필 (선택) — 투고 작가 SNS·블로그 링크 게재용. md 메타 `작가 SNS` 등에서 생성 */
  authorProfile?: { sns?: string; blog?: string; image?: string; bio?: string };
}

