/** 시리즈의 화 목록 (화 번호 순) */
export function getSeriesEpisodes(seriesId: string): LongTextData[] {
  return LONG_TEXT_DB.filter((t) => t.seriesId === seriesId).sort(
    (a, b) => (a.episode || 0) - (b.episode || 0)
  );
}

