    content: `할머니가 돌아가시고 마흔아홉 날이 지나서야, 나는 그 방의 문을 열었다.

장마가 막 시작된 유월의 끝이었다. 마당의 수국은 비를 맞아 고개를 숙이고 있었고, 처마 밑으로 낙숫물 떨어지는 소리가 일정했다. 사십구재를 지내고 온 식구가 큰집에 모였는데, 유품 정리는 어쩌다 보니 막내 손녀인 내 몫이 되었다. 아버지는 방문 앞까지 왔다가 끝내 들어오지 못하고 마당으로 나갔고, 고모는 부엌에서 이미 깨끗한 그릇을 자꾸만 닦았다.

오래 닫혀 있던 방에서는 마른 종이 냄새가 났다. 창문을 열자 빗소리가 방 안으로 밀려 들어왔고, 나는 그제야 이 방이 얼마나 오랫동안 조용했는지 알았다.

유품이라고 할 만한 것은 많지 않았다. 반듯하게 개켜진 이불 한 채. 알이 굵은 돋보기 두 개, 그중 하나는 부러진 다리에 반창고가 감겨 있었다. 손잡이가 반들반들해진 라디오. 자개가 반쯤 떨어져 나간 경대. 그리고 경대 서랍의 사진첩 사이에, 코팅까지 해 둔 상장이 한 장 끼워져 있었다. 면 복지관 한글교실 수료 기념, 성인문해교육 글쓰기 대회 장려상. 할머니의 이름 석 자가 굵은 글씨로 박혀 있었다.

장롱 아래 칸에서는 꽃무늬 보자기에 싸인 꾸러미가 나왔다. 매듭이 어찌나 단단한지 한참을 씨름해야 했다. 여러 번 묶고, 여러 번 풀어 본 매듭이었다.

보자기 안에는 공책 여섯 권이 들어 있었다. 표지가 바랜 옛날 국민학교 공책부터 문방구에서 파는 스프링 노트까지, 여섯 권은 하나같이 모서리가 둥글게 닳아 있었다. 수없이 넘겨 본 손길의 흔적이었다.

첫 장을 넘기고 나는 조금 웃었다. 연필로 꾹꾹 눌러쓴 글씨가 칸을 무시하고 삐뚤빼뚤 줄을 넘나들고 있었다.

공책에 적힌 것은 할머니의 이야기가 아니었다. 어디선가 듣고 본 문장들을 옮겨 적은 것이었다. 라디오에서 흘러나왔을 시 한 구절, 달력 뒷장에 인쇄된 격언, 드라마 대사, 심지어 약 봉투에 적힌 글귀까지.

첫 번째 공책의 첫 문장은 이랬다.

"꽃이 지는 것을 서러워 말 것."

나는 그 문장을 소리 내어 읽어 보았다. 빗소리 사이로 할머니의 목소리가 겹쳐 들리는 것 같았다.`,
