    id: 'batchim_ep7',
    title: '7화. 이름이 없는 아이',
    content: `품 안의 도둑은 버둥거리다가 이내 조용해졌다.

가까이서 보니 도둑은 준서보다도 작은 구름 아이였다. 몸은 뭉게뭉게 하얗고, 눈은 빗방울처럼 까맸다. 구름 아이는 준서를 물끄러미 올려다보더니 갑자기 눈물을 뚝뚝 흘렸다. 눈물은 떨어지면서 작은 이슬비가 되어 광장 바닥을 적셨다.

"받침을 왜 훔쳤어! 너 때문에 문이 무가 되고, 아저씨 손이 소가 됐잖아!"

준서가 다그치자 구름 아이는 기어들어 가는 목소리로 말했다.

"이름이... 갖고 싶어서."

"이름?"

"이 마을에서는 이름이 없으면 아무도 기억해 주지 않아. 나무도, 돌멩이도, 바람도 다 이름이 있는데 나만 없어. 나는 비 오는 날 하늘에서 떨어져 나왔는데, 아무도 나를 부르지 않아. 그냥 '하얀 것'이래. 사람들이 나를 보고도 금방 잊어버려. 어제 본 사람이 오늘 또 처음 보는 얼굴을 해."

구름 아이는 품에서 받침들을 꺼내 보였다. 니은, 리을, 이응.... 훔친 받침들이 손바닥 위에서 구슬처럼 반짝였다.

"받침은 글자를 꽉 붙잡아 주는 거잖아. 그래서 받침을 모으면 나도 이름을 만들 수 있을 줄 알았어. 그런데 아무리 이리 붙이고 저리 붙여 봐도, 이름이 되지 않아."

기역 대장이 다가와 조용히 말했다.

"당연하지. 이름이란 훔친 글자로 짓는 게 아니야. 누군가 너를 생각하면서, 너한테 어울리는 걸 골라서 지어 주는 거란다."

구름 아이는 고개를 푹 숙였다. 어깨가, 아니 몸 전체가 축 처져서 바닥에 닿을 것 같았다. 준서는 그 모습을 보다가, 저도 모르게 마음 한구석이 시큰해졌다.

아무도 이름을 불러 주지 않는 기분은, 어떤 걸까.`,
    category: '동화',
