    content: `한결이가 이사 간다는 말을 들은 건 중학교 3학년 늦가을이었다.

"아빠 회사 때문에. 남쪽으로. 바다 있는 데래."

급식실에서 식판을 사이에 두고, 한결이는 대단한 일도 아니라는 듯 말했다. 하지만 나는 그 애가 아무렇지 않은 척할 때 왼쪽 볼 안쪽을 깨문다는 걸 알고 있었다. 초등학교 2학년 때부터 팔 년을 붙어 다녔으니까. 나는 뭐라고 대답했는지 기억나지 않는다. 그날 급식 반찬이 제육볶음이었다는 것만 이상하게 기억난다.

이삿날을 일주일 앞둔 토요일, 우리는 시내 전망대에 올라갔다. 딱히 갈 데가 없어서였다. 오백 원짜리 망원경에 동전을 넣고 서로의 아파트를 찾아 주다가, 전망대 구석에서 그걸 발견했다. 빨간 우체통 옆에 서 있는, 짙은 초록색의 낡은 우체통. '느린 우체통'이라고 적혀 있었다.

"여기 넣으면 일 년 뒤에 배달해 준대."

한결이가 안내판을 읽더니 픽 웃었다.

"일 년 뒤에 받는 편지가 무슨 소용이야. 그때 가서 딴소리하고 있으면 어떡해."

"그러니까 재밌는 거지. 일 년 전의 나랑 대질심문 하는 거잖아."

우리는 전망대 매점에서 편지지를 샀다. 촌스러운 꽃무늬랑 더 촌스러운 바둑무늬 두 종류뿐이어서, 가위바위보로 정했다. 내가 이겨서 꽃무늬를 가졌다. 그리고 벤치에 등을 맞대고 앉아 편지를 썼다. 서로에게 쓰되, 절대 보여 주지 않기. 다 쓰면 바로 봉하기. 그게 규칙이었다.

나는 한결이의 등이 들썩이는 걸 느끼면서 내 편지를 썼다. 등 너머로 볼펜 소리가 사각사각 넘어왔다. 무슨 내용을 썼는지는, 그때는 나도 다 알고 있다고 생각했다.

편지 두 통이 초록색 우체통 속으로 사라졌다. 툭, 하고 바닥에 닿는 소리가 유난히 멀게 들렸다.

"일 년 뒤에 보자."

한결이가 말했다. 우리는 그게 무슨 뜻인지 그때는 깊이 생각하지 않았다.`,
