    id: 'yeobaek_ep10',
    title: '10화. 여백의 답장',
    content: `리모델링이 끝난 도서관은 낯설게 환했다.

새 책장, 새 바닥, 통유리 창. 그리고 제일 안쪽 구석에 여백 서가가 생겼다. 유리문이 달린 작은 책장에 스물여덟 권이 꽂혔고, 강 선생님이 만든 안내판이 붙었다. "이 책들은 여백의 기록 때문에 보존되었습니다. 낙서도 오래되면 역사가 됩니다."

개가식 첫날, 나는 『직업의 세계』를 마지막으로 한 번 더 펼쳤다.

1999년 12월의 메모 아래에는 여백이 조금 남아 있었다. 나는 가방에서 연필을 꺼냈다. 그리고 이십칠 년 만의 답장을 적었다.

"2026. 10. 읽었습니다. 칸이 없는 사람이 맞아서, 구석까지 왔습니다.

당신이 궁금해할 것 같아 적어 둡니다. 당신은 뭔가가 됐습니다. 지금도 책 사이에 있습니다. 하루의 모양대로 됐으니까, 그 겨울의 걱정은 여기서 그만하셔도 됩니다.

저는 아직 모릅니다. 뭐가 되고 싶은지는요. 대신 시키지 않아도 하는 일을 하나 찾았습니다. 옮겨 적는 일입니다. 남의 문장을 따라 쓰다 보면 제 문장이 어디쯤 있는지 보일 것 같아서요.

이 책은 이제 폐기되지 않습니다. 그러니 이 낙서도 안전할 겁니다. 먼 훗날 누가 이걸 읽는다면, 그 사람에게도 말해 주고 싶습니다. 칸이 없다고 사람이 없는 건 아니라고. 스물일곱 해 전에 어떤 선배가 그랬습니다. — ㄷ"

나는 책을 덮어 유리문 안에 꽂았다.

진로 희망서 1지망 칸에는 결국 '탐색 중'이라고 적어 냈다. 담임은 이번에는 한숨을 쉬지 않았다. 백지와 탐색 중 사이의 거리를, 담임도 아는 것 같았다.

어떤 질문은 답이 오는 데 이십칠 년이 걸린다. 그러니까 지금 답을 모르는 건, 어쩌면 아직 편지가 배달 중인 것뿐이다.`,
