    title: '1화. 비 오는 월요일',
    content: `세상에서 제일 별로인 요일은 월요일이다.

그건 우리 반 스물세 명 전원이 동의하는 몇 안 되는 사실이었다. 그런데 그 생각이 바뀐 것도 월요일이었다.

장맛비가 쏟아지던 월요일 아침, 나는 지각 직전이었다. 우산을 쓰고 운동장을 가로질러 뛰는데, 체육창고 뒤에서 이상한 소리가 들렸다. 낑, 하는 소리였다. 고양이 소리도 아니고 새소리도 아니었다.

무시하고 뛰려고 했다. 정말이다. 그런데 발이 먼저 멈췄다.

창고 뒤 처마 밑에, 개 한 마리가 웅크리고 있었다. 갈색 털이 비에 젖어 몸에 딱 붙어서, 원래보다 반은 작아 보였다. 목줄도 이름표도 없었다. 개는 나를 보더니 도망가지도 못하고, 그렇다고 다가오지도 못하고, 꼬리만 아주 조금, 정말 아주 조금 흔들었다.

그 꼬리가 문제였다.

"야, 조하준! 너 지각!"

교문 쪽에서 소민이가 소리쳤다. 같은 반 부반장 백소민. 나는 손짓으로 소민이를 불렀다. 소민이는 지각인데 왜 부르냐는 얼굴로 뛰어오다가, 개를 보더니 우뚝 멈췄다.

"...어떡해."

소민이가 말했다. 어떡해,에는 여러 종류가 있다. 불쌍해서 어떡해. 근데 우리가 뭘 어떡해. 소민이의 어떡해는 세 번째 종류였다. 그래서, 이제 우리 뭐부터 할까?의 어떡해.

지각을 십 분 남기고, 우리 둘은 개 앞에 쭈그려 앉았다.

그렇게 시작됐다. 6학년 1반의 열흘이.`,
