    title: '1화. 불면의 처방',
    content: `필사 모임에 등록한 건 순전히 잠 때문이었다.

프리랜서 삼 년 차. 집이 곧 작업실이 되면서 나의 하루는 경계를 잃었다. 새벽 세 시에 마감을 하고, 오후 한 시에 일어나고, 밤이 되면 말똥말똥해지는 생활. 몸은 피곤한데 머리가 꺼지지 않는 날이 이어졌다. 병원에 갈까 하다가, 동네 책방 유리문에 붙은 손글씨 안내문 앞에서 걸음이 멈췄다.

"화요일 밤의 필사 모임. 여덟 시부터 열 시까지. 좋은 문장을 손으로 옮겨 적습니다. 대화는 거의 하지 않습니다. 오시면 됩니다."

대화는 거의 하지 않습니다, 라는 문장이 마음에 들었다. 사람은 그립고 말은 부담스러운 상태. 서른 즈음의 프리랜서에게 흔한 병이었다.

책방 이름은 '틈'이었다. 여덟 평 남짓한 가게에 긴 나무 테이블이 하나 있고, 화요일 밤이면 거기에 예닐곱 명이 둘러앉았다. 규칙은 간단했다. 각자 가져온 책이나 책방의 책에서 마음에 드는 대목을 두 시간 동안 공책에 옮겨 적는다. 끝나기 십 분 전, 원하는 사람만 오늘 적은 문장 중 하나를 소리 내어 읽는다. 왜 골랐는지는 설명하지 않는다. 박수도 치지 않는다. 그게 다였다.

첫날, 나는 긴장해서 볼펜을 안 가져갔다는 걸 자리에 앉고서야 알았다.

가방을 뒤지는 소리가 커졌던 모양이다. 옆자리에서 볼펜 한 자루가 소리 없이 건너왔다. 검정색, 흔한 사무용 볼펜. 고개를 돌리자 남자는 이미 자기 공책으로 시선을 돌린 뒤였다.

그날 밤 나는 오랜만에 여섯 시간을 내리 잤다. 필사 덕인지, 다른 것 덕인지는 그때 알 수 없었다.`,
